-- ============================================================
-- 39. 热搜榜单结构化存储（多站点共用一张明细表）
-- ------------------------------------------------------------
-- 背景：hp_cache_res_hot_list 把整个月归档 JSON 塞进 body 一列（LONGTEXT），
--       /database 里预览只能看到一坨文本，无法按字段查询、排序、比对。
--       本文件把它按接口字段拆成「批次表 + 明细表」两层，所有视频网站的热搜
--       共用 hp_hot_search_item 一张表，用 source / channel 区分站点与榜单。
--
-- 表关系：
--   hp_hot_search_snapshot  一次抓取里的一个榜单（接口级元数据，一榜一行）
--   hp_hot_search_item      该榜单里的一条热搜（一条一行，嵌套字段全部摊平）
--   关联条件：source + channel_id + snapshot_at 相同即为同一批次
--
-- ── 腾讯视频 getSearchHotListHttp 字段映射 ──────────────────────
--   ret / msg                              → snapshot.ret_code / ret_msg
--   data.ErrCode / ErrMsg                  → snapshot.err_code / err_msg
--   data.Results[i].ChannelID/ChannelName → snapshot.channel_id / channel_name
--   data.Results[i].Result.TotalNum       → snapshot.total_num / item.total_num
--   data.Results[i].Result.ListInfo[j]    → item 一行，数组下标 +1 为 rank_no：
--     Query        → title          热搜词 / 作品名
--     SecondTitle  → subtitle       副标题（看点）
--     HotLevel     → hot_value      热度值
--     Trend        → trend          -1 降 / 0 平 / 1 升
--     ID           → item_id        视频 CID
--     URL          → item_url       跳转链接（接口多为空）
--     HzImgURL     → image_url      横版封面
--     VideoType    → item_type      内容类型编码（1/2/3/10 ...）
--     SourceType   → source_type    来源类型
--     Language2Query → extra_json.Language2Query（多语言映射，接口多为空对象）
--
-- ── 其它站点字段映射（同一张明细表） ──────────────────────────────
--   爱奇艺  /search/recommend/list  data.list[]
--     title/name → title, description → subtitle, albumId → item_id,
--     imageUrl → image_url, playUrl → item_url, channelId → item_type,
--     focus/score/videoCount/period → extra_json, data.result_num → total_num
--   B站    /x/v2/search/trending/ranking  data.list[] / data.top_list[]
--     keyword/show_name → title, position → rank_no, hot_id → item_id,
--     word_type → item_type, icon → image_url, score → hot_value
--   抖音    /aweme/v1/web/hot/search/list  data.word_list[] / data.trending_list[]
--     word → title, hot_value → hot_value, position → rank_no,
--     group_id/sentence_id → item_id, label/word_type → item_type,
--     word_cover → image_url, event_time/video_count → extra_json
--   微博    /ajax/statuses/hot_band  data.band_list[]（非视频站，同样兼容）
--     word/note → title, num → hot_value, realpos/rank → rank_no,
--     category/flag/icon_desc → extra_json
--   extra_json 只存「未被通用列覆盖」的原生字段，保证接口返回不丢字段。
--
-- ── 怎么看数据 ──────────────────────────────────────────────────
--   /database 页面选表 hp_hot_search_item 即可逐列预览（默认 100 行），
--   或选视图 hp_v_hot_search_latest 看各站各榜最新批次 Top10。
--   SELECT * FROM hp_hot_search_item WHERE source='tencent_video'
--     AND channel_name='电视剧' ORDER BY snapshot_at DESC, rank_no LIMIT 10;
--
-- 数据来源：.cache/api_responses/tencenthot_2026-11.json（2 个小时槽 × 9 榜）
--           + 爱奇艺 / B站 / 抖音脚本接口实时快照（中性条目抽样，仅作种子示例）。
-- 幂等：本文件先 DROP 再 CREATE，可单独重复执行；
--       mysql -u <user> -p <db> < sql/hot_search/39_hot_search.sql
-- ============================================================
SET NAMES utf8mb4;

DROP TABLE IF EXISTS `hp_hot_search_item`;
DROP TABLE IF EXISTS `hp_hot_search_snapshot`;

-- ── 榜单批次表：一次抓取 × 一个榜单 ───────────────────────────────
CREATE TABLE `hp_hot_search_snapshot` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `source` VARCHAR(32) NOT NULL COMMENT '站点编码：tencent_video / iqiyi / bilibili / douyin / weibo',
  `source_name` VARCHAR(32) NOT NULL COMMENT '站点中文名',
  `channel_id` VARCHAR(32) NOT NULL DEFAULT '' COMMENT '榜单 ID：腾讯 ChannelID / 爱奇艺 channel_id / B站与抖音的数组名',
  `channel_name` VARCHAR(64) NOT NULL DEFAULT '' COMMENT '榜单名：热搜 / 电视剧 / 电影 / 综艺 / 置顶 / 热点 等',
  `snapshot_at` DATETIME NOT NULL COMMENT '抓取时间槽：归档 entries 键，如 2026-11-20T23 → 2026-11-20 23:00:00',
  `asset_key` VARCHAR(64) NOT NULL DEFAULT '' COMMENT '来源归档键，如 2026-11（月归档）或 2026-11-28（实时快照）',
  `total_num` INT DEFAULT NULL COMMENT '接口声明的榜单总条数：Result.TotalNum / result_num',
  `item_count` INT NOT NULL DEFAULT 0 COMMENT '本次实际落库条数：ListInfo / list / word_list 长度',
  `err_code` VARCHAR(32) DEFAULT NULL COMMENT '接口状态码：ErrCode / code / status_code',
  `err_msg` VARCHAR(255) DEFAULT NULL COMMENT '接口消息：ErrMsg / message',
  `ret_code` INT DEFAULT NULL COMMENT '归档层返回码：entry.ret',
  `ret_msg` VARCHAR(255) DEFAULT NULL COMMENT '归档层消息：entry.msg',
  `api_url` VARCHAR(512) DEFAULT NULL COMMENT '数据来源接口地址',
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_batch` (`source`, `channel_id`, `snapshot_at`),
  KEY `idx_snapshot_time` (`snapshot_at`),
  KEY `idx_source_channel` (`source`, `channel_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='热搜榜单批次（接口级字段，多站点共用）';

-- ── 热搜明细表：一条热搜一行，所有视频站共用 ──────────────────────
CREATE TABLE `hp_hot_search_item` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `source` VARCHAR(32) NOT NULL COMMENT '站点编码，同 hp_hot_search_snapshot.source',
  `source_name` VARCHAR(32) NOT NULL COMMENT '站点中文名',
  `channel_id` VARCHAR(32) NOT NULL DEFAULT '' COMMENT '榜单 ID，同批次表',
  `channel_name` VARCHAR(64) NOT NULL DEFAULT '' COMMENT '榜单名，同批次表',
  `snapshot_at` DATETIME NOT NULL COMMENT '抓取时间槽，同批次表',
  `asset_key` VARCHAR(64) NOT NULL DEFAULT '' COMMENT '来源归档键',
  `rank_no` INT NOT NULL COMMENT '榜单名次（数组下标 +1，或接口 position / realpos）',
  `title` VARCHAR(255) NOT NULL COMMENT '热搜词 / 作品名：Query / title / keyword / word / name',
  `subtitle` VARCHAR(512) DEFAULT NULL COMMENT '副标题 / 看点 / 简介：SecondTitle / description / note',
  `hot_value` BIGINT DEFAULT NULL COMMENT '热度值：HotLevel / hot_value / num / score',
  `hot_text` VARCHAR(64) DEFAULT NULL COMMENT '热度展示文本，如 15.5万（接口无此字段时留空）',
  `trend` TINYINT DEFAULT NULL COMMENT '趋势：Trend，-1 下降 / 0 持平 / 1 上升',
  `item_id` VARCHAR(128) DEFAULT NULL COMMENT '内容 ID：ID(CID) / albumId / hot_id / group_id / sentence_id',
  `item_type` VARCHAR(32) DEFAULT NULL COMMENT '内容类型：VideoType / word_type / channelId / label',
  `item_url` VARCHAR(512) DEFAULT NULL COMMENT '跳转链接：URL / playUrl / hotlist_param',
  `image_url` VARCHAR(512) DEFAULT NULL COMMENT '封面图 / 图标：HzImgURL / imageUrl / icon / word_cover',
  `source_type` INT DEFAULT NULL COMMENT '来源类型：SourceType（其它站可复用为 label）',
  `total_num` INT DEFAULT NULL COMMENT '该榜单接口声明的总条数：Result.TotalNum',
  `extra_json` JSON DEFAULT NULL COMMENT '未被通用列覆盖的原生字段，保留接口原始形态以便核对',
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_item` (`source`, `channel_id`, `snapshot_at`, `rank_no`),
  KEY `idx_source_channel_rank` (`source`, `channel_name`, `snapshot_at`, `rank_no`),
  KEY `idx_title` (`title`(64)),
  KEY `idx_hot_value` (`source`, `hot_value`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='热搜明细（腾讯视频/爱奇艺/B站/抖音等共用，逐字段摊平）';

-- ============================================================
-- 种子数据：真实接口响应展开，初始化后即可直接 SELECT 看到每一行
-- ============================================================
-- 快照批次：22 行；明细：374 行；来源：{"tencent_video":340,"iqiyi":10,"bilibili":10,"douyin":14}











