  ('iqiyi','爱奇艺','0','热搜','2026-11-28 17:00:00','2026-11-28',1,'两京十五日','改编自马伯庸所著同名小说，讲述了身在南京的太子朱瞻基被卷入惊天阴谋之际，与捕快吴定缘、女医苏荆溪和小官于谦一道躲开层层追捕，在十五日内借道大运河返回京城受诏的故事。',NULL,NULL,NULL,'3190714930072901','2','http://www.iqiyi.com/v_1ewmjgivkm4.html','http://pic9.iqiyipic.com/image/20261118/ea/9d/a_100693385_m_601_m8.jpg',NULL,15,'{"sourceId":0,"videoCount":26,"latestOrder":18,"period":"2026-11-25","categories":[],"exclusive":1,"qiyiProduced":1,"focus":"限时闯关“京”险不断","isAdvance":false,"payMark":0,"payMarkUrl":"http://pic0.iqiyipic.com/common/20171106/ac/1b/vip_100000_v_601.png","score":0,"pingback":{"doc_id":3190714930072901}}'),
  ('iqiyi','爱奇艺','0','热搜','2026-11-28 17:00:00','2026-11-28',2,'欢迎来龙餐馆','徐福为养家还债远赴中东中餐馆当厨师，在当地结识了大堂经理马俊生。他们以地道中国风味广招八方来客，龙餐馆声名鹊起。然而随着战争爆发，当地形势急转直下，没有人能够独善其身，徐福和马俊生也不例外，他们的命运将何去何从？战火中的龙餐馆又将如何维系？',NULL,NULL,NULL,'5322069590536500','1','http://www.iqiyi.com/v_1fl5vbynu54.html','http://pic8.iqiyipic.com/image/20261127/10/c4/v_211275582_m_601_m3.jpg',NULL,15,'{"tvId":5322069590536500,"isAdvance":false,"payMark":1,"payMarkUrl":"http://pic0.iqiyipic.com/common/20171106/ac/1b/vip_100000_v_601.png","duration":"02:20:08","videoCount":1,"latestOrder":1,"categories":["战争","喜剧"],"albumName":"欢迎来龙餐馆","albumImageUrl":"","period":"2026-08-11","exclusive":false,"qiyiProduced":false,"sourceId":0,"focus":"沈腾开店笑料百出","score":9.2,"imageProductionType":["IMAGE_PRODUCTION_TYPE_ON_DEMAND","IMAGE_PRODUCTION_TYPE_PREPARATION"],"pingback":{"doc_id":5322069590536500}}'),
  ('iqiyi','爱奇艺','0','热搜','2026-11-28 17:00:00','2026-11-28',3,'音乐缘计划第3季','原创音综再进一阶！实力歌手与宝藏音乐人双向奔赴，从选歌、改歌到共创舞台，把原创作品真正唱进观众心里。经典模式全面焕新，更强阵容、更有梗关系、更鲜活名场面，让好歌被听见，让原创冲出下一首全民爆款！',NULL,NULL,NULL,'8465757544548401','6','http://www.iqiyi.com/v_140615i8k2g.html','http://pic0.iqiyipic.com/image/20260923/33/9f/a_100797657_m_601_m2.jpg',NULL,15,'{"sourceId":8465757544548401,"videoCount":0,"latestOrder":0,"period":"2026-11-28","people":{"guest":[{"id":214966605,"name":"薛之谦"},{"id":214357505,"name":"容祖儿"},{"id":223266205,"name":"周深"}]},"categories":["爱奇艺出品","内地"],"exclusive":1,"qiyiProduced":1,"focus":"原创音综再进一阶","isAdvance":false,"payMark":0,"payMarkUrl":"http://pic0.iqiyipic.com/common/20171106/ac/1b/vip_100000_v_601.png","score":8.9,"pingback":{"doc_id":8465757544548401}}'),
  ('iqiyi','爱奇艺','0','热搜','2026-11-28 17:00:00','2026-11-28',4,'小城良方','该剧讲述了当天才医生刘铮亮（肖战饰）遭遇人生滑铁卢，被迫返回家乡从零开始的故事。他就地集结一群“不靠谱”的人，热血操刀着“最靠谱”的事。在烟火气中以人情暖意编织市井日常，开出一剂剂疗愈心灵的人生处方。',NULL,NULL,NULL,'3993682943621001','2','http://www.iqiyi.com/v_eienwprun0.html','http://pic6.iqiyipic.com/image/20261102/1e/06/a_100692840_m_601_m8.jpg',NULL,15,'{"sourceId":0,"videoCount":29,"latestOrder":29,"period":"2026-10-30","people":{"main_charactor":[{"id":232480305,"name":"肖战"},{"id":214988805,"name":"丁嘉丽"},{"id":205041305,"name":"王彦霖"}]},"categories":["都市"],"exclusive":1,"qiyiProduced":1,"focus":"纯过日子，嘎嘎回血！","isAdvance":false,"payMark":0,"payMarkUrl":"http://pic0.iqiyipic.com/common/20171106/ac/1b/vip_100000_v_601.png","score":8.8,"pingback":{"doc_id":3993682943621001}}'),
  ('iqiyi','爱奇艺','0','热搜','2026-11-28 17:00:00','2026-11-28',5,'风生水起','警员唐晋责（韩东君饰）卧底捣毁 "黑蛇" 组织后，与杨静雅（傅菁饰）相恋，却在婚前旅行遭报复，杨静雅 "身亡"，他自此消沉。三年后渝江市再发要案，唐晋责加入专案组重出江湖，多起环环相扣的单元案件接连上演，从诈骗绑架到连环命案，背后牵出惊天阴谋，杨静雅竟 "死而复生"。经过唐晋责和其他警员的层层追查，终将幕后黑手绳之以法，成功守护了一方净土。',NULL,NULL,NULL,'4218289380984901','2','http://www.iqiyi.com/v_hzb9amhrv8.html','http://pic1.iqiyipic.com/image/20261128/27/ef/a_101682454_m_601_m8.jpg',NULL,15,'{"sourceId":0,"videoCount":24,"latestOrder":8,"period":"2026-11-15","people":{"main_charactor":[{"id":214500405,"name":"韩东君"},{"id":238584005,"name":"傅菁"}]},"categories":["悬疑","内地","普通话"],"exclusive":0,"qiyiProduced":0,"focus":"猎奇罪案，连环迷局","isAdvance":false,"payMark":0,"payMarkUrl":"http://pic0.iqiyipic.com/common/20171106/ac/1b/vip_100000_v_601.png","score":0,"pingback":{"doc_id":4218289380984901}}'),
  ('iqiyi','爱奇艺','0','热搜','2026-11-28 17:00:00','2026-11-28',6,'伟大的长征','以中央红军长征为主线，全面反映了从红军第五次反围剿失败，到红⼀、红⼆、红四方面军和红二十五军在中共中央领导下先后实施战略转移，经历了艰苦卓绝的长征，最终取得胜利的历史过程，讴歌了以毛泽东同志为代表的中国共产党⼈坚定的理想信念、百折不挠的革命精神，阐明中国革命发生发展的历史原因和历史逻辑，以及马克思主义必须和中国革命的具体实践相结合才能指导中国革命取得胜利的深刻道理。',NULL,NULL,NULL,'3023062267902001','2','http://www.iqiyi.com/v_1jm50v4hx7c.html','http://pic5.iqiyipic.com/image/20261009/f0/68/a_100688277_m_601_m6.jpg',NULL,15,'{"sourceId":0,"videoCount":60,"latestOrder":60,"period":"2026-11-09","people":{"main_charactor":[{"id":201879605,"name":"于和伟"},{"id":238075605,"name":"王劲松"},{"id":208363505,"name":"朱刚日尧"}]},"categories":[],"exclusive":0,"qiyiProduced":1,"focus":"英雄史诗不朽丰碑","isAdvance":false,"payMark":0,"payMarkUrl":"http://pic0.iqiyipic.com/common/20171106/ac/1b/vip_100000_v_601.png","score":0,"pingback":{"doc_id":3023062267902001}}'),
  ('iqiyi','爱奇艺','0','热搜','2026-11-28 17:00:00','2026-11-28',7,'奔跑吧大湾区篇','醒狮腾跃，鱼灯摇曳，城市地标与岭南文化元素交织相映，共同绘就生动鲜活的大湾区图景。跟随#奔跑吧大湾区篇# 的脚步走进这里，领略岭南风情，感受城市发展的崭新面貌。',NULL,NULL,NULL,'5697483204143901','6','http://www.iqiyi.com/v_wous9g50is.html','http://pic0.iqiyipic.com/image/20261120/27/0d/a_101687771_m_601_m4.jpg',NULL,15,'{"sourceId":5697483204143901,"videoCount":0,"latestOrder":0,"period":"2026-11-24","categories":[],"exclusive":0,"qiyiProduced":0,"focus":"嚟啦，玩嘢！","isAdvance":false,"payMark":1,"payMarkUrl":"http://pic0.iqiyipic.com/common/20171106/ac/1b/vip_100000_v_601.png","score":0,"pingback":{"doc_id":5697483204143901}}'),
  ('iqiyi','爱奇艺','0','热搜','2026-11-28 17:00:00','2026-11-28',8,'八仙!','八个身份各异的凡人因不同机缘稀里糊涂凑在了蓬莱仙境，有人临时起意有人开团秒跟，他们假扮神仙花式作死准备干票大的，却怎料一个惊天阴谋，正悄咪咪朝他们砸过来，这场啼笑皆非的奇幻之旅，最终会走向何处呢？',NULL,NULL,NULL,'7513586686238400','1','http://www.iqiyi.com/v_226vd5pgu5o.html','http://pic8.iqiyipic.com/image/20261104/c4/32/v_200795824_m_601_m3.jpg',NULL,15,'{"tvId":7513586686238400,"isAdvance":false,"payMark":1,"payMarkUrl":"http://pic0.iqiyipic.com/common/20171106/ac/1b/vip_100000_v_601.png","duration":"02:23:16","videoCount":1,"latestOrder":1,"categories":[],"albumName":"八仙！","albumImageUrl":"","period":"2026-07-18","exclusive":false,"qiyiProduced":false,"sourceId":0,"focus":"草台班子集结笑闹仙关","score":9,"imageProductionType":["IMAGE_PRODUCTION_TYPE_ON_DEMAND","IMAGE_PRODUCTION_TYPE_PREPARATION"],"pingback":{"doc_id":7513586686238400}}'),
  ('iqiyi','爱奇艺','0','热搜','2026-11-28 17:00:00','2026-11-28',9,'疯狂动物城2','兔子朱迪与狐狸尼克正式组成搭档，合作侦破一桩棘手案件。一个神秘蛇类嫌疑人乱入动物城，引发连环谜团。这对新搭档在面对暗流涌动的危险时，再次成为全城的希望。他们能否揭开真相，为城市带来正义？故事充满冒险、智慧和温暖，令人期待。',NULL,NULL,NULL,'6797252583814800','1','http://www.iqiyi.com/v_1vf32rlbi7w.html','http://pic5.iqiyipic.com/image/20260403/96/75/v_185154253_m_601_m4.jpg',NULL,15,'{"tvId":6797252583814800,"isAdvance":false,"payMark":1,"payMarkUrl":"http://pic0.iqiyipic.com/common/20171106/ac/1b/vip_100000_v_601.png","duration":"01:43:26","videoCount":1,"latestOrder":1,"categories":[],"albumName":"疯狂动物城2","albumImageUrl":"","period":"2025-11-26","exclusive":false,"qiyiProduced":false,"sourceId":0,"focus":"狐兔搭档破惊天大案","people":{"main_charactor":[{"id":214706905,"name":"金妮弗·古德温"},{"id":215055405,"name":"杰森·贝特曼"},{"id":228684005,"name":"关继威"}]},"score":9,"imageProductionType":["IMAGE_PRODUCTION_TYPE_ON_DEMAND","IMAGE_PRODUCTION_TYPE_PREPARATION"],"pingback":{"doc_id":6797252583814800}}'),
  ('iqiyi','爱奇艺','0','热搜','2026-11-28 17:00:00','2026-11-28',10,'折月亮','故事讲述了傅识则（林一 饰）与云厘（卢昱晓 饰）在南芜重逢，外人面前严重社恐的少女云厘为向父亲证明自己能够独立生活，报考了南芜的研究生，并在开学前夕接受南芜当地一家VR体验馆的邀请，以视频UP主的身份参与体验活动，重遇高中时期被她当作白月光贴在床头的天才少年傅识则。云厘从暗恋到明恋，一改社恐本性，在一干人等的助攻下，花式主动追求傅识则。终于她小太阳一般的光芒深深照进傅识则的心里，成功抱得男神归。恋爱时光虽甜蜜，两人在问题处理和认知上的分歧却逐渐显现，最终阴差阳错矛盾引爆，导致两人分手，云厘出国，傅识则深埋心底的伤痛往事也显露于人前。为了能够再度追回云厘，傅识则重新振作，带领团队重攀科研巅峰，并在云厘回国后花式追妻，两人最终消除芥蒂，再续前缘。',NULL,NULL,NULL,'5033289882239001','2','http://www.iqiyi.com/v_1nj820ys5vg.html','http://pic8.iqiyipic.com/image/20261106/4d/10/a_100671203_m_601_m7.jpg',NULL,15,'{"sourceId":0,"videoCount":27,"latestOrder":27,"period":"2026-11-12","people":{"main_charactor":[{"id":1650556502485205,"name":"卢昱晓"},{"id":240667205,"name":"林一"},{"id":238257805,"name":"卢洋洋"}]},"categories":["言情","青春","剧情"],"exclusive":1,"qiyiProduced":1,"focus":"双向暗恋，心动奔赴","isAdvance":false,"payMark":0,"payMarkUrl":"http://pic0.iqiyipic.com/common/20171106/ac/1b/vip_100000_v_601.png","score":0,"pingback":{"doc_id":5033289882239001}}'),
